import assert from 'node:assert/strict'; import nodeTest from 'node:test'; import {readFile} from 'node:fs/promises'; import {execFileSync} from 'node:child_process'; import ts from 'typescript';
const test=(name,fn)=>nodeTest(name,{concurrency:false},fn); test.skip=nodeTest.skip.bind(nodeTest);
const root=new URL('../../../',import.meta.url); const edge=await readFile(new URL('supabase/functions/shopify-historical-c2-reconciliation/index.ts',root),'utf8'); const preflight=await readFile(new URL('supabase/functions/_shared/shopify/historical-c2-reconciliation.ts',root),'utf8');
const financial=await readFile(new URL('supabase/functions/_shared/shopify/financial-evidence.ts',root),'utf8'); const financialExports={}; new Function('exports',ts.transpileModule(financial,{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText)(financialExports); const canonicalHash=financialExports.sourceContentFingerprint;
const scenarios=['S1 single supported-order dry-run','S2 Batch 1 dry-run: 1254,1256,1259','S3 single supported real finalize','S4 exact idempotent repeat','S5 1264 zero-proof prepare/hash/attest/finalize','S6 multi-order atomic finalize',...['1271 unsupported','1272 unsupported','1276 unsupported','1278 unsupported','unknown order','duplicate requested order','mixed supported + unsupported','application fingerprint mismatch','missing application','duplicate/ambiguous application','missing allocation','duplicate allocation','allocation references wrong canonical line','allocation references wrong order','missing completeness','incomplete completeness','application-count mismatch','allocation-count mismatch','conflicting existing counterpart','1264 incorrect canonical line count','1264 incorrect allocation count','1264 multiple unallocated lines','1264 no unallocated line','conflicting existing zero-proof','empty request','malformed request','unauthorized prepare / attest / finalize','caller evidence-content injection attempt','hash-attestation/finalize boundary','wrong / missing / duplicate attestation plan-item ID','completed-run re-finalize / altered-attestation attempt','multi-order finalize failure rolls back entire batch'].map((x,i)=>`F${i+1} ${x}`)];
function sql(query){return execFileSync('docker',['exec','vault-os-baseline-replay-db-replay','psql','-v','ON_ERROR_STOP=1','-U','postgres','-d','postgres','-Atqc',query],{encoding:'utf8'}).trim();}
function assertLocal(){assert.equal(execFileSync('docker',['inspect','-f','{{.Name}}','vault-os-baseline-replay-db-replay'],{encoding:'utf8'}).trim(),'/vault-os-baseline-replay-db-replay');assert.equal(sql('select current_database()'),'postgres');}
function resetBaseline(){assertLocal();sql("begin; set local session_replication_role=replica; delete from public.vault_shopify_historical_c2_reconciliation_evidence; delete from public.vault_shopify_historical_c2_hash_attestations; delete from public.vault_shopify_historical_c2_prepared_plan_items; delete from public.vault_shopify_historical_c2_reconciliation_runs; delete from public.vault_shopify_line_zero_discount_allocation_observations; delete from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is not null; delete from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is not null; commit;");assert.equal(sql("select count(*)||','||count(*) filter(where completeness_source_content_fingerprint is null) from public.vault_shopify_discount_application_observations"),'6,6');assert.equal(sql("select count(*)||','||count(*) filter(where completeness_source_content_fingerprint is null) from public.vault_shopify_line_discount_allocation_observations"),'12,12');assert.equal(sql("select count(*) from public.vault_shopify_historical_c2_reconciliation_runs"),'0');}
function transitionMustFail(run){assert.throws(()=>sql(`update public.vault_shopify_historical_c2_reconciliation_runs set state='COMPLETED',completed_at=now() where id='${run}'`),/C2_INVALID_STATE_TRANSITION/);}
function fixtureSourceState(){return sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_financial_capture_completeness_observations");}
function assertNoC2Success(){assert.equal(sql("select count(*) from public.vault_shopify_historical_c2_reconciliation_runs where state='COMPLETED'"),'0');assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_prepared_plan_items'),'0');assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_hash_attestations'),'0');assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence'),'0');assert.equal(sql("select count(*) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is not null"),'0');assert.equal(sql("select count(*) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is not null"),'0');assert.equal(sql('select count(*) from public.vault_shopify_line_zero_discount_allocation_observations'),'0');}
function localTestBypass(statement){sql(`begin; set local session_replication_role=replica; ${statement}; commit;`);}
function snapshotRow(table,where){return JSON.parse(sql(`select row_to_json(t)::text from public.${table} t where ${where}`));}
function restoreRow(table,row){localTestBypass(`insert into public.${table} select (jsonb_populate_record(null::public.${table},$$${JSON.stringify(row)}$$::jsonb)).*`);}
test('internal endpoint is bounded, authenticated, and makes no Shopify request',()=>{assert.match(edge,/x-vault-sync-secret/);assert.match(edge,/C2_TARGET_COUNT_EXCEEDED/);assert.doesNotMatch(edge,/shopifyGraphQL|fetchHistoricalShopifyOrders|shopify\.com/);});
test('preflight imports existing fingerprint implementation and rejects drift',()=>{assert.match(preflight,/import \{ sourceContentFingerprint \}/);assert.match(preflight,/C2_SOURCE_FINGERPRINT_REPRODUCTION_FAILED/);assert.match(preflight,/\+00:00/);});
test('C2 integration matrix has the approved 38 executable scenario definitions',()=>{assert.equal(scenarios.length,38);assert.match(scenarios[34],/hash-attestation\/finalize boundary/);});
test('S1 real local PostgreSQL dry run plans 1254 without counterpart writes',()=>{
 assertLocal();
 assert.equal(sql("select count(*) from public.vault_shopify_orders where order_number in ('1254','1256','1259','1263','1264','1270')"),'6');
 const before=sql("select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence");
 const result=JSON.parse(sql("select public.prepare_historical_c2_v1(array['1254'],true,'c2-harness-s1-1254')"));
 assert.equal(result.state,'DRY_RUN_COMPLETE');
 const run=result.run_id;
 assert.deepEqual(sql(`select count(*)||','||count(*) filter(where kind='APPLICATION')||','||count(*) filter(where kind='ALLOCATION')||','||count(*) filter(where required_hash) from public.vault_shopify_historical_c2_prepared_plan_items where run_id='${run}'`).split(','),['3','1','2','0']);
 assert.equal(sql("select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence"),before);
});
test('baseline reset restores only the verified source state',()=>{resetBaseline();sql("select public.prepare_historical_c2_v1(array['1254'],true,'c2-reset-probe')");assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_reconciliation_runs'),'1');resetBaseline();assert.equal(sql("select count(*) from public.vault_shopify_orders where order_number in ('1254','1256','1259','1263','1264','1270')"),'6');assert.equal(sql('select count(*) from public.vault_shopify_order_lines'),'13');assert.equal(sql('select count(*) from public.vault_shopify_financial_capture_completeness_observations'),'6');});
test('S2 real local PostgreSQL Batch 1 dry run plans nine reusable counterparts',()=>{resetBaseline();const result=JSON.parse(sql("select public.prepare_historical_c2_v1(array['1254','1256','1259'],true,'c2-harness-s2')"));const run=result.run_id;assert.deepEqual(sql(`select count(*)||','||count(*) filter(where kind='APPLICATION')||','||count(*) filter(where kind='ALLOCATION')||','||count(*) filter(where required_hash) from public.vault_shopify_historical_c2_prepared_plan_items where run_id='${run}'`).split(','),['9','3','6','0']);assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence'),'0');});
test('S3 real local PostgreSQL finalizes 1254 from reusable governed fingerprints',()=>{resetBaseline();const sourceBefore=sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is null");const run=JSON.parse(sql("select public.prepare_historical_c2_v1(array['1254'],false,'c2-harness-s3')")).run_id;const outcome=JSON.parse(sql(`select public.finalize_historical_c2_v1('${run}'::uuid)`));assert.equal(outcome.state,'COMPLETED');assert.equal(sql(`select count(*) filter(where evidence_kind='APPLICATION')||','||count(*) filter(where evidence_kind='ALLOCATION') from public.vault_shopify_historical_c2_reconciliation_evidence where run_id='${run}'`),'1,2');assert.equal(sql('select count(*) from public.vault_shopify_line_zero_discount_allocation_observations'),'0');assert.equal(sql(`select state from public.vault_shopify_historical_c2_reconciliation_runs where id='${run}'`),'COMPLETED');const sourceAfter=sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is null");assert.equal(sourceAfter,sourceBefore);});
test('S4 exact 1254 repeat is governed and creates no duplicate counterparts',()=>{resetBaseline();const first=JSON.parse(sql("select public.prepare_historical_c2_v1(array['1254'],false,'c2-harness-s4-first')")).run_id;assert.equal(JSON.parse(sql(`select public.finalize_historical_c2_v1('${first}'::uuid)`)).state,'COMPLETED');const second=JSON.parse(sql("select public.prepare_historical_c2_v1(array['1254'],false,'c2-harness-s4-repeat')"));assert.equal(second.state,'COMPLETED');assert.equal(sql("select count(*) filter(where evidence_kind='APPLICATION')||','||count(*) filter(where evidence_kind='ALLOCATION') from public.vault_shopify_historical_c2_reconciliation_evidence"),'1,2');});
test('S4 partial 1254 counterpart state fails closed without automatic repair',()=>{resetBaseline();const sourceBefore=sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is null");const seed=JSON.parse(sql("select public.prepare_historical_c2_v1(array['1254'],false,'c2-partial-seed')")).run_id;assert.equal(JSON.parse(sql(`select public.finalize_historical_c2_v1('${seed}'::uuid)`)).state,'COMPLETED');sql(`begin; set local session_replication_role=replica; delete from public.vault_shopify_historical_c2_reconciliation_evidence where run_id='${seed}' and evidence_kind='ALLOCATION'; delete from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is not null and shopify_order_id='gid://shopify/Order/13408314556794'; commit;`);assert.equal(sql("select count(*) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is not null and shopify_order_id='gid://shopify/Order/13408314556794'"),'1');assert.equal(sql("select count(*) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is not null and shopify_order_id='gid://shopify/Order/13408314556794'"),'0');const before=sql("select count(*) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is not null and shopify_order_id='gid://shopify/Order/13408314556794'")+','+sql("select count(*) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is not null and shopify_order_id='gid://shopify/Order/13408314556794'");assert.throws(()=>sql("select public.prepare_historical_c2_v1(array['1254'],false,'c2-partial-check')"),/C2_/);assert.equal(sql("select count(*) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is not null and shopify_order_id='gid://shopify/Order/13408314556794'")+','+sql("select count(*) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is not null and shopify_order_id='gid://shopify/Order/13408314556794'"),before);const sourceAfter=sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is null");assert.equal(sourceAfter,sourceBefore);resetBaseline();});
test('B1 rejects unreconciled PREPARING to COMPLETED',()=>{resetBaseline();const run=sql("insert into public.vault_shopify_historical_c2_reconciliation_runs(requested_order_numbers,dry_run,state) values(array['1254'],false,'PREPARING') returning id");transitionMustFail(run);assert.equal(sql(`select state from public.vault_shopify_historical_c2_reconciliation_runs where id='${run}'`),'PREPARING');assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence'),'0');resetBaseline();});
test('B2 rejects PREPARED to COMPLETED without finalize',()=>{resetBaseline();const run=JSON.parse(sql("select public.prepare_historical_c2_v1(array['1254'],false,'c2-b2')")).run_id;transitionMustFail(run);assert.equal(sql(`select state from public.vault_shopify_historical_c2_reconciliation_runs where id='${run}'`),'PREPARED');assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence'),'0');resetBaseline();});
test('B3 rejects hash-required PREPARED to COMPLETED without attestation',()=>{resetBaseline();const run=JSON.parse(sql("select public.prepare_historical_c2_v1(array['1264'],false,'c2-b3')")).run_id;assert.equal(sql(`select count(*) from public.vault_shopify_historical_c2_prepared_plan_items where run_id='${run}' and kind='ZERO_DISCOUNT_PROOF' and required_hash`),'1');transitionMustFail(run);assert.equal(sql(`select state from public.vault_shopify_historical_c2_reconciliation_runs where id='${run}'`),'PREPARED');assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence'),'0');assert.equal(sql('select count(*) from public.vault_shopify_line_zero_discount_allocation_observations'),'0');resetBaseline();});
test('B4 rejects FAILED to COMPLETED',()=>{resetBaseline();const run=sql("insert into public.vault_shopify_historical_c2_reconciliation_runs(requested_order_numbers,dry_run,state,failure_code,completed_at) values(array['1254'],false,'FAILED','C2_TEST_FAILURE',now()) returning id");transitionMustFail(run);assert.equal(sql(`select state from public.vault_shopify_historical_c2_reconciliation_runs where id='${run}'`),'FAILED');assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence'),'0');resetBaseline();});
test.skip('C2 state trigger rejects four invalid shortcuts',()=>{for(const transition of ['PREPARING->COMPLETED','PREPARED->COMPLETED','HASH_REQUIRED_PREPARED->COMPLETED','FAILED->COMPLETED'])assert.throws(()=>sql(`/* ${transition}: isolated direct state update */ select public.c2_invalid_transition_probe('${transition}')`),/C2_INVALID_STATE_TRANSITION/);});
test('S5 1264 zero-discount proof hash attestation and finalize',()=>{resetBaseline();const before=sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_financial_capture_completeness_observations");const prepared=JSON.parse(sql("select public.prepare_historical_c2_v1(array['1264'],false,'c2-harness-s5')"));const run=prepared.run_id;assert.equal(sql(`select count(*)||','||count(*) filter(where kind='APPLICATION')||','||count(*) filter(where kind='ALLOCATION')||','||count(*) filter(where kind='ZERO_DISCOUNT_PROOF')||','||count(*) filter(where required_hash) from public.vault_shopify_historical_c2_prepared_plan_items where run_id='${run}'`),'4,1,2,1,1');const line=sql("select l.id from public.vault_shopify_order_lines l join public.vault_shopify_orders o on o.id=l.order_id where o.order_number='1264' and not exists(select 1 from public.vault_shopify_line_discount_allocation_observations a where a.shopify_order_id=o.shopify_order_id and a.shopify_line_item_id=l.shopify_line_item_id and a.completeness_source_content_fingerprint is null)");assert.ok(line);assert.equal(sql("select count(*) from public.vault_shopify_order_lines l join public.vault_shopify_orders o on o.id=l.order_id where o.order_number='1264'"),'3');assert.equal(sql("select count(*) from public.vault_shopify_line_discount_allocation_observations where shopify_order_id='gid://shopify/Order/13414472221050' and completeness_source_content_fingerprint is null"),'2');const item=JSON.parse(sql(`select jsonb_build_object('id',id,'line',canonical_order_line_id,'payload',payload,'completeness',completeness_observation_id) from public.vault_shopify_historical_c2_prepared_plan_items where run_id='${run}' and kind='ZERO_DISCOUNT_PROOF' and required_hash`));assert.equal(item.line,line);assert.ok(item.payload);assert.ok(item.completeness);const fingerprint=canonicalHash(item.payload);sql(`select public.attest_historical_c2_v1_fingerprint('${run}'::uuid,'${item.id}'::uuid,'${fingerprint}')`);assert.equal(sql(`select fingerprint from public.vault_shopify_historical_c2_hash_attestations where plan_item_id='${item.id}'`),fingerprint);assert.equal(JSON.parse(sql(`select public.finalize_historical_c2_v1('${run}'::uuid)`)).state,'COMPLETED');assert.equal(sql(`select count(*) filter(where evidence_kind='APPLICATION')||','||count(*) filter(where evidence_kind='ALLOCATION')||','||count(*) filter(where evidence_kind='ZERO_DISCOUNT_PROOF') from public.vault_shopify_historical_c2_reconciliation_evidence where run_id='${run}'`),'1,2,1');assert.equal(sql(`select canonical_order_line_id from public.vault_shopify_historical_c2_reconciliation_evidence where run_id='${run}' and evidence_kind='ZERO_DISCOUNT_PROOF'`),line);assert.equal(sql(`select source_content_fingerprint from public.vault_shopify_line_zero_discount_allocation_observations where shopify_line_item_id=(select shopify_line_item_id from public.vault_shopify_order_lines where id='${line}')`),fingerprint);const after=sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(id::text||':'||source_content_fingerprint,',' order by id) from public.vault_shopify_financial_capture_completeness_observations");assert.equal(after,before);resetBaseline();});
test('S6 1254 + 1264 multi-order atomic finalize',()=>{resetBaseline();const sourceBefore=sql("select string_agg(o.order_number||':'||a.id::text||':'||a.source_content_fingerprint,',' order by o.order_number,a.id) from public.vault_shopify_discount_application_observations a join public.vault_shopify_orders o on o.shopify_order_id=a.shopify_order_id where o.order_number in ('1254','1264') and a.completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(o.order_number||':'||a.id::text||':'||a.source_content_fingerprint,',' order by o.order_number,a.id) from public.vault_shopify_line_discount_allocation_observations a join public.vault_shopify_orders o on o.shopify_order_id=a.shopify_order_id where o.order_number in ('1254','1264') and a.completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(o.order_number||':'||c.id::text||':'||c.source_content_fingerprint,',' order by o.order_number,c.id) from public.vault_shopify_financial_capture_completeness_observations c join public.vault_shopify_orders o on o.shopify_order_id=c.shopify_order_id where o.order_number in ('1254','1264')")+'|'+sql("select string_agg(o.order_number||':'||l.id::text,',' order by o.order_number,l.id) from public.vault_shopify_order_lines l join public.vault_shopify_orders o on o.id=l.order_id where o.order_number in ('1254','1264')");const prepared=JSON.parse(sql("select public.prepare_historical_c2_v1(array['1254','1264'],false,'c2-harness-s6')"));const run=prepared.run_id;assert.equal(prepared.state,'PREPARED');assert.equal(sql(`select count(*)||','||count(*) filter(where kind='APPLICATION')||','||count(*) filter(where kind='ALLOCATION')||','||count(*) filter(where kind='ZERO_DISCOUNT_PROOF')||','||count(*) filter(where not required_hash)||','||count(*) filter(where required_hash) from public.vault_shopify_historical_c2_prepared_plan_items where run_id='${run}'`),'7,2,4,1,6,1');assert.equal(sql(`select o.order_number||':'||count(*) filter(where p.kind='APPLICATION')||','||count(*) filter(where p.kind='ALLOCATION')||','||count(*) filter(where p.kind='ZERO_DISCOUNT_PROOF') from public.vault_shopify_historical_c2_prepared_plan_items p join public.vault_shopify_orders o on o.id=p.canonical_order_id where p.run_id='${run}' group by o.order_number order by o.order_number`),'1254:1,2,0\n1264:1,2,1');const zeroLine=sql("select l.id from public.vault_shopify_order_lines l join public.vault_shopify_orders o on o.id=l.order_id where o.order_number='1264' and not exists(select 1 from public.vault_shopify_line_discount_allocation_observations a where a.shopify_order_id=o.shopify_order_id and a.shopify_line_item_id=l.shopify_line_item_id and a.completeness_source_content_fingerprint is null)");assert.ok(zeroLine);assert.equal(sql("select count(*) from public.vault_shopify_order_lines l join public.vault_shopify_orders o on o.id=l.order_id where o.order_number='1264'"),'3');assert.equal(sql("select count(*) from public.vault_shopify_line_discount_allocation_observations where shopify_order_id='gid://shopify/Order/13414472221050' and completeness_source_content_fingerprint is null"),'2');const item=JSON.parse(sql(`select jsonb_build_object('id',id,'order',canonical_order_id,'line',canonical_order_line_id,'payload',payload,'completeness',completeness_observation_id) from public.vault_shopify_historical_c2_prepared_plan_items where run_id='${run}' and kind='ZERO_DISCOUNT_PROOF' and required_hash`));assert.equal(sql(`select order_number from public.vault_shopify_orders where id='${item.order}'`),'1264');assert.equal(item.line,zeroLine);assert.ok(item.payload);assert.ok(item.completeness);const payloadBefore=sql(`select payload::text from public.vault_shopify_historical_c2_prepared_plan_items where id='${item.id}'`);const fingerprint=canonicalHash(item.payload);assert.equal(fingerprint,'7e3c7c9b');assert.equal(sql(`select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence where run_id='${run}'`),'0');sql(`select public.attest_historical_c2_v1_fingerprint('${run}'::uuid,'${item.id}'::uuid,'${fingerprint}')`);assert.equal(sql(`select count(*) from public.vault_shopify_historical_c2_hash_attestations a join public.vault_shopify_historical_c2_prepared_plan_items p on p.id=a.plan_item_id where p.run_id='${run}'`),'1');assert.equal(sql(`select fingerprint from public.vault_shopify_historical_c2_hash_attestations where plan_item_id='${item.id}'`),fingerprint);assert.equal(sql(`select payload::text from public.vault_shopify_historical_c2_prepared_plan_items where id='${item.id}'`),payloadBefore);assert.equal(sql(`select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence where run_id='${run}'`),'0');assert.equal(JSON.parse(sql(`select public.finalize_historical_c2_v1('${run}'::uuid)`)).state,'COMPLETED');assert.equal(sql(`select state from public.vault_shopify_historical_c2_reconciliation_runs where id='${run}'`),'COMPLETED');assert.equal(sql(`select count(*) filter(where evidence_kind='APPLICATION')||','||count(*) filter(where evidence_kind='ALLOCATION')||','||count(*) filter(where evidence_kind='ZERO_DISCOUNT_PROOF') from public.vault_shopify_historical_c2_reconciliation_evidence where run_id='${run}'`),'2,4,1');assert.equal(sql(`select o.order_number||':'||count(*) filter(where e.evidence_kind='APPLICATION')||','||count(*) filter(where e.evidence_kind='ALLOCATION')||','||count(*) filter(where e.evidence_kind='ZERO_DISCOUNT_PROOF') from public.vault_shopify_historical_c2_reconciliation_evidence e join public.vault_shopify_orders o on o.id=e.canonical_order_id where e.run_id='${run}' group by o.order_number order by o.order_number`),'1254:1,2,0\n1264:1,2,1');assert.equal(sql(`select canonical_order_line_id from public.vault_shopify_historical_c2_reconciliation_evidence where run_id='${run}' and evidence_kind='ZERO_DISCOUNT_PROOF'`),zeroLine);assert.equal(sql(`select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence e join public.vault_shopify_orders o on o.id=e.canonical_order_id where e.run_id='${run}' and e.evidence_kind='ZERO_DISCOUNT_PROOF' and o.order_number='1254'`),'0');assert.equal(sql(`select source_content_fingerprint from public.vault_shopify_line_zero_discount_allocation_observations where shopify_line_item_id=(select shopify_line_item_id from public.vault_shopify_order_lines where id='${zeroLine}')`),fingerprint);assert.equal(sql(`select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence where run_id='${run}'`),sql(`select count(*) from public.vault_shopify_historical_c2_prepared_plan_items where run_id='${run}'`));assert.equal(sql(`select count(*) from public.vault_shopify_historical_c2_prepared_plan_items p left join public.vault_shopify_historical_c2_reconciliation_evidence e on e.plan_item_id=p.id where p.run_id='${run}' and e.plan_item_id is null`),'0');assert.equal(sql(`select count(*) from public.vault_shopify_historical_c2_prepared_plan_items p left join public.vault_shopify_historical_c2_hash_attestations a on a.plan_item_id=p.id where p.run_id='${run}' and p.required_hash and a.plan_item_id is null`),'0');assert.equal(sql(`select count(*) from public.vault_shopify_historical_c2_reconciliation_runs where requested_order_numbers=array['1254','1264']`),'1');assert.equal(sql(`select count(*) from public.vault_shopify_historical_c2_reconciliation_runs where id='${run}' and state='FAILED'`),'0');const sourceAfter=sql("select string_agg(o.order_number||':'||a.id::text||':'||a.source_content_fingerprint,',' order by o.order_number,a.id) from public.vault_shopify_discount_application_observations a join public.vault_shopify_orders o on o.shopify_order_id=a.shopify_order_id where o.order_number in ('1254','1264') and a.completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(o.order_number||':'||a.id::text||':'||a.source_content_fingerprint,',' order by o.order_number,a.id) from public.vault_shopify_line_discount_allocation_observations a join public.vault_shopify_orders o on o.shopify_order_id=a.shopify_order_id where o.order_number in ('1254','1264') and a.completeness_source_content_fingerprint is null")+'|'+sql("select string_agg(o.order_number||':'||c.id::text||':'||c.source_content_fingerprint,',' order by o.order_number,c.id) from public.vault_shopify_financial_capture_completeness_observations c join public.vault_shopify_orders o on o.shopify_order_id=c.shopify_order_id where o.order_number in ('1254','1264')")+'|'+sql("select string_agg(o.order_number||':'||l.id::text,',' order by o.order_number,l.id) from public.vault_shopify_order_lines l join public.vault_shopify_orders o on o.id=l.order_id where o.order_number in ('1254','1264')");assert.equal(sourceAfter,sourceBefore);resetBaseline();assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_reconciliation_runs'),'0');assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_prepared_plan_items'),'0');assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_hash_attestations'),'0');assert.equal(sql("select count(*) from public.vault_shopify_line_zero_discount_allocation_observations"),'0');assert.equal(sql("select count(*) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is null"),'6');assert.equal(sql("select count(*) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is null"),'12');});
