test('F8 1254 application fingerprint mismatch fails closed',()=>{resetBaseline();const before=fixtureSourceState();const application=JSON.parse(sql("select jsonb_build_object('id',id,'source',source,'order_id',shopify_order_id,'application_index',application_index,'updated_at',order_source_updated_at,'fingerprint',source_content_fingerprint,'payload_fingerprint',payload_fingerprint,'contract',fingerprint_contract_version) from public.vault_shopify_discount_application_observations where shopify_order_id='gid://shopify/Order/13408314556794' and completeness_source_content_fingerprint is null"));try{sql(`begin; set local session_replication_role=replica; update public.vault_shopify_discount_application_observations set source_content_fingerprint='deadbeef' where id='${application.id}'; commit;`);const mutated=JSON.parse(sql(`select jsonb_build_object('id',id,'source',source,'order_id',shopify_order_id,'application_index',application_index,'updated_at',order_source_updated_at,'fingerprint',source_content_fingerprint,'payload_fingerprint',payload_fingerprint,'contract',fingerprint_contract_version) from public.vault_shopify_discount_application_observations where id='${application.id}'`));assert.equal(sql("select count(*) from public.vault_shopify_discount_application_observations where shopify_order_id='gid://shopify/Order/13408314556794' and completeness_source_content_fingerprint is null"),'1');assert.deepEqual({...mutated,fingerprint:application.fingerprint},application);assert.equal(mutated.fingerprint,'deadbeef');assert.notEqual(fixtureSourceState(),before);assert.throws(()=>sql("select public.prepare_historical_c2_v1(array['1254'],false,'c2-f8')"),/C2_APPLICATION_ATTESTATION_FAILED/);assertNoC2Success();}finally{sql(`begin; set local session_replication_role=replica; update public.vault_shopify_discount_application_observations set source_content_fingerprint='${application.fingerprint}' where id='${application.id}'; commit;`);assert.equal(fixtureSourceState(),before);assert.throws(()=>sql(`update public.vault_shopify_discount_application_observations set source_content_fingerprint=source_content_fingerprint where id='${application.id}'`),/Shopify financial evidence is append-only/);resetBaseline();assertNoC2Success();assert.equal(fixtureSourceState(),before);}});
