test('F29 hash-attestation finalize boundary is governed',()=>{resetBaseline();const run=JSON.parse(sql("select public.prepare_historical_c2_v1(array['1264'],false,'c2-f29')")).run_id;const item=JSON.parse(sql(`select jsonb_build_object('id',id,'payload',payload) from public.vault_shopify_historical_c2_prepared_plan_items where run_id='${run}' and required_hash`));assert.throws(()=>sql(`select public.finalize_historical_c2_v1('${run}'::uuid)`),/C2_HASH_ATTESTATION_MISSING/);assert.equal(sql('select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence'),'0');assert.equal(sql(`select state from public.vault_shopify_historical_c2_reconciliation_runs where id='${run}'`),'PREPARED');assert.throws(()=>sql(`begin; set local role authenticated; select public.attest_historical_c2_v1_fingerprint('${run}'::uuid,'${item.id}'::uuid,'deadbeef'); commit;`),/permission denied/);const fp=canonicalHash(item.payload);assert.equal(JSON.parse(sql(`select public.attest_historical_c2_v1_fingerprint('${run}'::uuid,'${item.id}'::uuid,'${fp}')`)).attested,true);assert.equal(JSON.parse(sql(`select public.attest_historical_c2_v1_fingerprint('${run}'::uuid,'${item.id}'::uuid,'${fp}')`)).idempotent,true);assert.throws(()=>sql(`select public.attest_historical_c2_v1_fingerprint('${run}'::uuid,'${item.id}'::uuid,'deadbeef')`),/C2_HASH_ATTESTATION_CONFLICT/);const payload=sql(`select payload::text from public.vault_shopify_historical_c2_prepared_plan_items where id='${item.id}'`),identity=sql(`select id||':'||expected_source_fingerprint from public.vault_shopify_historical_c2_prepared_plan_items where id='${item.id}'`),counts=sql("select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence")+','+sql('select count(*) from public.vault_shopify_historical_c2_hash_attestations');assert.throws(()=>sql(`update public.vault_shopify_historical_c2_prepared_plan_items set payload='{}' where id='${item.id}'`),/C2_PREPARED_PLAN_IMMUTABLE/);assert.equal(sql(`select payload::text from public.vault_shopify_historical_c2_prepared_plan_items where id='${item.id}'`),payload);assert.equal(sql(`select id||':'||expected_source_fingerprint from public.vault_shopify_historical_c2_prepared_plan_items where id='${item.id}'`),identity);assert.equal(sql(`select state from public.vault_shopify_historical_c2_reconciliation_runs where id='${run}'`),'PREPARED');assert.equal(sql("select count(*) from public.vault_shopify_historical_c2_reconciliation_evidence")+','+sql('select count(*) from public.vault_shopify_historical_c2_hash_attestations'),counts);resetBaseline();});
