test('F32 multi-order finalize rolls back atomically on later zero-proof write failure',()=>{resetBaseline();const before=fixtureSourceState();const run=JSON.parse(sql("select public.prepare_historical_c2_v1(array['1254','1264'],false,'c2-f32')")).run_id;assert.equal(sql(`select count(*)||','||count(*) filter(where kind='APPLICATION')||','||count(*) filter(where kind='ALLOCATION')||','||count(*) filter(where kind='ZERO_DISCOUNT_PROOF')||','||count(*) filter(where required_hash) from public.vault_shopify_historical_c2_prepared_plan_items where run_id='${run}'`),'7,2,4,1,1');const item=JSON.parse(sql(`select jsonb_build_object('id',id,'payload',payload) from public.vault_shopify_historical_c2_prepared_plan_items where run_id='${run}' and required_hash`));const fp=canonicalHash(item.payload);assert.equal(fp,'7e3c7c9b');sql(`select public.attest_historical_c2_v1_fingerprint('${run}'::uuid,'${item.id}'::uuid,'${fp}')`);try{sql("create function public.vault_test_c2_finalize_fault_f32() returns trigger language plpgsql as $$begin raise exception 'F32_TEST_INJECTED_FINALIZE_FAILURE'; end$$");sql("create trigger vault_test_c2_finalize_fault_f32_trigger before insert on public.vault_shopify_line_zero_discount_allocation_observations for each row when (new.shopify_order_id='gid://shopify/Order/13414472221050') execute function public.vault_test_c2_finalize_fault_f32()");assert.throws(()=>sql(`select public.finalize_historical_c2_v1('${run}'::uuid)`),/F32_TEST_INJECTED_FINALIZE_FAILURE/);assert.equal(sql("select count(*) from public.vault_shopify_discount_application_observations where completeness_source_content_fingerprint is not null"),'0');assert.equal(sql("select count(*) from public.vault_shopify_line_discount_allocation_observations where completeness_source_content_fingerprint is not null"),'0');assert.equal(sql('select count(*) from public.vault_shopify_line_zero_discount_allocation_observations'),'0');assert.equal(sql(`select state from public.vault_shopify_historical_c2_reconciliation_runs where id='${run}'`),'PREPARED');assert.equal(fixtureSourceState(),before);}finally{sql('drop trigger if exists vault_test_c2_finalize_fault_f32_trigger on public.vault_shopify_line_zero_discount_allocation_observations');sql('drop function if exists public.vault_test_c2_finalize_fault_f32()');resetBaseline();assert.equal(fixtureSourceState(),before);}});
